'use client'

import * as React from 'react'
import { cn } from "@/lib/utils"

const Checkbox = React.forwardRef<
  HTMLButtonElement,
  Omit<
    React.ButtonHTMLAttributes<HTMLButtonElement>,
    'checked' | 'defaultChecked' | 'onChange' | 'value'
  > & {
    checked?: boolean | 'indeterminate'
    defaultChecked?: boolean | 'indeterminate'
    required?: boolean
    onCheckedChange?: (checked: boolean | 'indeterminate') => void
    value?: string
  }
>(
  (
    {
      className,
      checked: checkedProp,
      defaultChecked,
      required,
      onCheckedChange,
      value = 'on',
      disabled,
      ...props
    },
    ref
  ) => {
    const isControlled = checkedProp !== undefined
    const [uncontrolledChecked, setUncontrolledChecked] = React.useState<boolean | 'indeterminate'>(
      defaultChecked ?? false
    )
    const isChecked = isControlled ? checkedProp : uncontrolledChecked

    const setChecked = React.useCallback(
      (nextChecked: boolean | 'indeterminate') => {
        if (!isControlled) {
          setUncontrolledChecked(nextChecked)
        }
        onCheckedChange?.(nextChecked)
      },
      [isControlled, onCheckedChange]
    )

    const handleClick = (e: React.MouseEvent<HTMLButtonElement>) => {
      const nextChecked = isChecked === 'indeterminate' ? true : !isChecked
      setChecked(nextChecked)
      props.onClick?.(e)
    }

    return (
      <label data-slot="checkbox-root" className="inline-flex items-center">
        <button
          type="button"
          role="checkbox"
          aria-checked={isChecked === 'indeterminate' ? 'mixed' : isChecked}
          data-state={
            isChecked === 'indeterminate' ? 'indeterminate' : isChecked ? 'checked' : 'unchecked'
          }
          data-slot="checkbox"
          disabled={disabled}
          value={value}
          className={cn(
            'peer border-input data-[state=checked]:bg-primary data-[state=checked]:text-primary-foreground data-[state=checked]:border-primary focus-visible:border-ring focus-visible:ring-ring/50 aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive size-4 shrink-0 rounded-[4px] border shadow-xs transition-shadow outline-none focus-visible:ring-[3px] disabled:cursor-not-allowed disabled:opacity-50',
            className
          )}
          ref={ref}
          onClick={handleClick}
          {...props}
        >
          <div
            data-slot="checkbox-indicator"
            className={cn(
              'flex items-center justify-center text-current opacity-0 transition-opacity duration-100',
              isChecked && 'opacity-100'
            )}
          >
            {isChecked === 'indeterminate' ? (
              <span className="h-0.5 w-2 rounded-full bg-current" />
            ) : (
              <svg
                aria-hidden="true"
                viewBox="0 0 16 16"
                fill="none"
                stroke="currentColor"
                strokeWidth="3"
                strokeLinecap="round"
                strokeLinejoin="round"
                className="size-3.5"
              >
                <path d="M3.5 8.5l3 3 6-7" />
              </svg>
            )}
          </div>
        </button>
        <input
          type="checkbox"
          className="sr-only"
          checked={isChecked === true}
          readOnly
          disabled={disabled}
          required={required}
          value={value}
        />
      </label>
    )
  }
)
Checkbox.displayName = 'Checkbox'

export { Checkbox }

import { computed } from "vue";
import { normalizeProps, useMachine } from "@zag-js/vue";
import { checkboxConnect, checkboxMachine } from "@/lib/utils";
import type { CheckboxVueProps } from "@/lib/utils";

type UseCheckboxEmit = {
    (event: "update:modelValue", value: boolean | "indeterminate"): void;
    (event: "update:checked", value: boolean | "indeterminate"): void;
    (event: "change", value: boolean | "indeterminate"): void;
};

export function useCheckbox(props: CheckboxVueProps, emit: UseCheckboxEmit) {
    const machineProps = computed(() => ({
        id: props.id,
        checked: props.modelValue ?? props.checked,
        defaultChecked:
            props.modelValue === undefined && props.checked === undefined
                ? props.defaultChecked
                : undefined,
        disabled: props.disabled,
        required: props.required,
        name: props.name,
        value: props.value,
        onCheckedChange(details: { checked: boolean | "indeterminate" }) {
            emit("update:modelValue", details.checked);
            emit("update:checked", details.checked);
            emit("change", details.checked);
        },
    }));

    const service = useMachine(checkboxMachine, machineProps);
    const api = computed(() => checkboxConnect(service, normalizeProps));

    return api;
}

import type { CheckboxProps } from "@/lib/utils"

import { checkboxVariants } from '../utils'

type CheckboxWeappProps = CheckboxProps & {
  extClass?: string
}

const checkboxProps = {
  checked: { type: null, value: false },
  defaultChecked: { type: null, value: false },
  disabled: { type: Boolean, value: false },
  required: { type: Boolean, value: false },
  readOnly: { type: Boolean, value: false },
  invalid: { type: Boolean, value: false },
  name: { type: String, value: '' },
  form: { type: String, value: '' },
  value: { type: String, value: 'on' },
  id: { type: String, value: '' },
  extClass: { type: String, value: '' },
} satisfies Partial<Record<keyof CheckboxWeappProps, any>>

Component({
  externalClasses: ['ext-class'],
  properties: checkboxProps,
  data: {
    className: '',
    checked: false,
    indeterminate: false,
  },
  observers: {
    'checked, defaultChecked, disabled, extClass': function () {
      // Checkbox variants in shared do not have variants yet, just base strings.
      // But they might use data attributes in React.
      // For WeApp, we just apply the base class + extClass.
      // Ideally we should pass state to variants if cva supported it, but cva uses `variants` prop.
      // The shared variant uses `data-[state=checked]`. We need to simulate this or just use the base if static.
      // Wait, the shared variant relies heavily on `data-[state=checked]` selectors which Tailwind maps to attribute selectors.
      // In WeApp we don't have data attributes driving CSS in the same way with native Tailwind unless we use specific utility classes.
      // But wait! The shared definition is: `data-[state=checked]:bg-primary ...`
      // WeApp doesn't support attribute selectors in WXSS efficiently or at all for Tailwind JIT in this way unless we shim it.
      // STRATEGY: We will resolve the class string assuming the state is passed as a variant OR manually toggle classes?
      // actually, `cva` doesn't handle `data-state` automatically unless it's a compound variant.
      // The React component uses `cn(checkboxStyles(), className)`.
      // The styles rely on the specific dom element having `data-state="checked"`.
      // In WeApp, we must CONDITIONALLY apply these classes or use a utility that maps state to class.
      // For now, I will implement a basic version and potentially refine the shared variant to use "variants" instead of data-attributes for better portability?
      // NO, I must use the Shared Universal Variants.
      // If the shared variant uses `data-[state=checked]`, I can't easily use it in WeApp without that attribute.
      // However, I can pass `class="... data-[state=checked]"`? No, that's a selector.
      // I need to add `data-state="{{checked ? 'checked' : 'unchecked'}}"` to the view in WXML!
      // And strict Tailwind extraction needs to see it? No, raw string is fine.
      this.setData({
        className: checkboxVariants({ className: this.properties.extClass }),
      })
    },
    checked: function (checked) {
      if (checked === 'indeterminate') {
        this.setData({ checked: false, indeterminate: true })
        return
      }
      if (typeof checked === 'boolean') {
        this.setData({ checked, indeterminate: false })
      }
    },
  },
  lifetimes: {
    attached() {
      const checkedProp = this.properties.checked
      const defaultChecked = this.properties.defaultChecked
      const resolved =
        checkedProp === 'indeterminate'
          ? 'indeterminate'
          : typeof checkedProp === 'boolean'
            ? checkedProp
            : defaultChecked
      this.setData({
        checked: resolved === true,
        indeterminate: resolved === 'indeterminate',
      })
    },
  },
})

.checkbox-tree {
  display: flex;
  flex-direction: column;
  gap: 12rpx;
}

.checkbox-tree-item {
  display: flex;
  align-items: center;
  gap: 12rpx;
}

.checkbox-tree-label {
  font-size: 28rpx;
  color: #111827;
}

type CheckboxTreeNode = {
  id: string
  label: string
  checked?: boolean
  disabled?: boolean
  children?: CheckboxTreeNode[]
}

type FlatNode = CheckboxTreeNode & { level: number }

const flattenNodes = (nodes: CheckboxTreeNode[], level = 0, acc: FlatNode[] = []) => {
  nodes.forEach((node) => {
    acc.push({
      ...node,
      level,
    })
    if (Array.isArray(node.children) && node.children.length > 0) {
      flattenNodes(node.children, level + 1, acc)
    }
  })
  return acc
}

Component({
  options: {
    styleIsolation: 'apply-shared',
  },

  properties: {
    nodes: {
      type: Array,
      value: [],
    },
    checkedKeys: {
      type: Array,
      value: [],
    },
    extClass: {
      type: String,
      value: '',
    },
  },

  data: {
    flatNodes: [] as FlatNode[],
    checkedMap: {} as Record<string, boolean>,
  },

  lifetimes: {
    attached() {
      this.syncFromProps()
    },
  },

  observers: {
    'nodes, checkedKeys': function () {
      this.syncFromProps()
    },
  },

  methods: {
    syncFromProps() {
      const flatNodes = flattenNodes((this.properties.nodes || []) as CheckboxTreeNode[])
      const checkedMap: Record<string, boolean> = {}
      ;(this.properties.checkedKeys as string[]).forEach((id) => {
        checkedMap[id] = true
      })
      flatNodes.forEach((node) => {
        if (node.checked && checkedMap[node.id] === undefined) {
          checkedMap[node.id] = true
        }
      })
      this.setData({ flatNodes, checkedMap })
    },

    onToggle(e: WechatMiniprogram.BaseEvent) {
      const id = e.currentTarget.dataset.id as string
      if (!id) return
      const checkedMap = { ...(this.data.checkedMap || {}) }
      checkedMap[id] = !checkedMap[id]
      const checkedKeys = Object.keys(checkedMap).filter((key) => checkedMap[key])
      this.setData({ checkedMap })
      this.triggerEvent('change', {
        checkedKeys,
      })
      this.triggerEvent('update:checkedKeys', checkedKeys)
    },
  },
})
